## Additive regression tests

**A wire-shape pin must be asserted in every exit-0 mode, especially the degraded ones.** The tests parse the JSON, assert exactly one top-level key, assert `entries` is `{}` (not `null`), and assert every field is zero — for both absent and empty storage.

```go
func assertZeroJSON(t *testing.T, out bytes.Buffer) {
	t.Helper()
	line := strings.TrimRight(out.String(), "\n")
	if strings.Count(line, "\n") != 0 {
		t.Fatalf("--json must print exactly one line, got %q", out.String())
	}
	var top map[string]json.RawMessage
	if err := json.Unmarshal([]byte(line), &top); err != nil {
		t.Fatalf("--json output not parseable: %v (%q)", err, line)
	}
	raw, ok := top["report"]
	if !ok || len(top) != 1 {
		t.Fatalf(`want exactly one top-level key "report", got %v`, top)
	}
	var report struct {
		Entries   map[string]int `json:"entries"`
		Total     int            `json:"total"`
		Unhealthy int            `json:"unhealthy"`
	}
	if err := json.Unmarshal(raw, &report); err != nil {
		t.Fatalf("report payload invalid: %v", err)
	}
	if report.Entries == nil {
		t.Fatal("empty map must serialise as {}, not null")
	}
	if report.Total != 0 || report.Unhealthy != 0 {
		t.Fatalf("zero-value report expected, got %+v", report)
	}
}

func TestDegradedJSONAbsent(t *testing.T) { /* run --json over missing file, assertZeroJSON */ }
func TestDegradedJSONEmpty(t *testing.T)  { /* run --json over empty file,  assertZeroJSON */ }
```

